If the critical source map file is missing or malformed, `readJson` will throw an unhandled exception and crash the script. To fail closed gracefully, wrap the load in a try-catch block and return a failed validation status with appropriate diagnostics.

```javascript
export async function buildFigureAssetSourcePageRenders(options = {}) {
  const root = path.resolve(options.root ?? repoRootFromScript());
  const paths = { ...DEFAULT_PATHS, ...(options.paths ?? {}) };
  const generatedAt = options.generatedAt ?? DEFAULT_GENERATED_AT;
  const dpi = Number(options.dpi ?? DEFAULT_DPI);

  let sourceMap;
  try {
    sourceMap = options.sourceMap ?? readJson(root, paths.sourceMapIn);
  } catch (error) {
    const validatorResult = {
      schema_version: 'figureasset_source_page_renders_validator.v1',
      generated_at: generatedAt,
      summary: { 
        validation_status: 'fail',
        check_count: 1,
        failed_check_count: 1,
        rendered_page_count: 0,
        missing_page_count: 0,
        duplicate_reuse_count: 0,
      },
      checks: [
        {
          id: 'source_map_load',
          status: 'fail',
          summary: 'Failed to load source map: ' + (error instanceof Error ? error.message : String(error)),
        },
      ],
    };
    const manifest = {
      schema_version: 'figureasset_source_page_renders.v1',
      generated_at: generatedAt,
      summary: {
        validation_status: 'fail',
      },
      page_renders: [],
      row_mappings: [],
    };
    return { manifest, readback: 'Failed to load source map.', validatorResult };
  }

  const outputRoot = paths.outputRoot;
  const rendererVersion = options.rendererVersion ?? defaultRendererVersion(root);
  const renderPage = options.renderPage ?? renderPdfPageWithPdfjs;
  const renderer = options.renderer ?? null;
