+    if (pageNumber1Based > document.numPages) {
+      throw new Error(`source_page_out_of_range: page ${pageNumber1Based} exceeds PDF page count ${document.numPages}`);
+    }
+    const page = await document.getPage(pageNumber1Based);
+    const baseViewport = page.getViewport({ scale: 1 });
+    const scale = dpi / 72;
+    const viewport = page.getViewport({ scale });
+    const renderCanvas = loaded.canvas.createCanvas(Math.ceil(viewport.width), Math.ceil(viewport.height));
+    await page.render({ canvasContext: renderCanvas.getContext('2d'), viewport }).promise;
+    page.cleanup();
+    fs.mkdirSync(path.dirname(outputPath), { recursive: true });
+    fs.writeFileSync(outputPath, await renderCanvas.encode('png'));
+    return {
+      page_width_points: baseViewport.width,
+      page_height_points: baseViewport.height,
+      image_width_pixels: renderCanvas.width,
+      image_height_pixels: renderCanvas.height,
+      nonblank_pixel_sample_count: estimateNonblankPixelSignal(renderCanvas),
+    };
+  } finally {
+    await document.destroy();
+  }
+}
